insert into public.ajustes (id, popup) values (1, true) on conflict (id) do update set popup = excluded.popup;
insert into public.destinos (url, orden, nombre, h1, region, corto, foto, alt, foto2, alt2, titulo_seo, descripcion_seo, lead, h2, parrafos, vivir, datos, otros) values ('guatape', 1, '{"es":"Guatapé","en":"Guatapé"}'::jsonb, '{"es":"Guatapé y la Piedra del Peñol","en":"Guatapé and the Piedra del Peñol"}'::jsonb, '{"es":"Antioquia · a 2 horas de Medellín","en":"Antioquia · 2 hours from Medellín"}'::jsonb, '{"es":"Zócalos de colores y la Piedra del Peñol.","en":"Colorful zócalos and the Piedra del Peñol."}'::jsonb, 'guatape.jpg', '{"es":"Embalse de Guatapé con sus islas verdes visto desde lo alto","en":"Guatapé reservoir and its green islands seen from above"}'::jsonb, 'guatape-calle.jpg', '{"es":"Calle con fachadas de colores y zócalos en Guatapé","en":"Street with colorful facades and zócalos in Guatapé"}'::jsonb, '{"es":"Guatapé y la Piedra del Peñol desde Medellín · Wanna Go","en":"Guatapé and the Piedra del Peñol from Medellín · Wanna Go"}'::jsonb, 'Viaje a Guatapé desde Medellín: sube la Piedra del Peñol, recorre las calles de zócalos y navega el embalse. Diseñado a tu medida por Wanna Go.', '{"es":"El pueblo de los zócalos y la piedra que mira sobre un mar de islas. A dos horas de Medellín, uno de los paisajes más fotografiados de Colombia.","en":"The town of painted zócalos and the rock that looks out over a sea of islands. Two hours from Medellín, one of the most photographed landscapes in Colombia."}'::jsonb, '{"es":"Color, agua y montaña","en":"Color, water and mountains"}'::jsonb, '[{"es":"Guatapé es un pueblo de calles empedradas donde cada casa cuenta su historia en los zócalos: relieves de colores en la base de las fachadas que muestran oficios, animales y escenas de la vida local.","en":"Guatapé is a town of cobbled streets where every house tells its story through its zócalos: colorful reliefs along the base of the façades depicting trades, animals and scenes of local life."},{"es":"Muy cerca está la Piedra del Peñol. Quien sube sus más de 700 escalones encuentra arriba una vista completa del embalse, con sus islas y penínsulas verdes. Con nosotros lo recorres sin afán, con tiempo para el agua, la cocina local y la conversación.","en":"Nearby stands the Piedra del Peñol. Those who climb its more than 700 steps are rewarded with a full view of the reservoir, its islands and green peninsulas. With us you explore it unhurried, with time for the water, local food and conversation."}]'::jsonb, '[{"titulo":{"es":"Subir la Piedra del Peñol","en":"Climb the Piedra del Peñol"},"texto":{"es":"Más de 700 escalones y una de las vistas más amplias de Antioquia.","en":"More than 700 steps up to one of the widest views in Antioquia."}},{"titulo":{"es":"Calles de zócalos","en":"Streets of zócalos"},"texto":{"es":"Un recorrido a pie por las fachadas pintadas y sus historias.","en":"A walk past the painted façades and the stories they tell."}},{"titulo":{"es":"Paseo por el embalse","en":"Out on the reservoir"},"texto":{"es":"Lancha o velero entre islas, bahías y fincas a la orilla del agua.","en":"Boat or sailboat among islands, bays and lakeside farms."}},{"titulo":{"es":"Cocina de pueblo","en":"Small-town cooking"},"texto":{"es":"Trucha, bandeja paisa y postres de la región en lugares que conocemos.","en":"Trout, bandeja paisa and regional desserts at places we know well."}}]'::jsonb, '{"llegar":{"es":"2 horas por carretera desde Medellín","en":"2 hours by road from Medellín"},"epoca":{"es":"Todo el año","en":"Year-round"},"tiempo":{"es":"1 o 2 días","en":"1 or 2 days"},"ideal":{"es":"Familias, parejas y grupos","en":"Families, couples and groups"}}'::jsonb, array['comuna-13', 'plazas-de-mercado', 'eje-cafetero']::text[]);
insert into public.destinos (url, orden, nombre, h1, region, corto, foto, alt, foto2, alt2, titulo_seo, descripcion_seo, lead, h2, parrafos, vivir, datos, otros) values ('comuna-13', 2, '{"es":"Comuna 13","en":"Comuna 13"}'::jsonb, '{"es":"Comuna 13, Medellín","en":"Comuna 13, Medellín"}'::jsonb, '{"es":"Medellín · barrio San Javier","en":"Medellín · San Javier district"}'::jsonb, '{"es":"Grafiti, hip hop y una historia de transformación.","en":"Graffiti, hip hop and a story of transformation."}'::jsonb, 'comuna13.jpg', '{"es":"Casas de colores y murales en las laderas de la Comuna 13","en":"Colorful houses and murals on the hillsides of Comuna 13"}'::jsonb, 'medellin-montanas.jpg', '{"es":"Edificios de Medellín frente a las montañas","en":"Medellín buildings against the mountains"}'::jsonb, '{"es":"Tour por la Comuna 13 de Medellín · Wanna Go","en":"Comuna 13 tour in Medellín · Wanna Go"}'::jsonb, 'Recorre la Comuna 13 de Medellín con guías del barrio: grafitis, escaleras eléctricas, hip hop y la historia de su transformación. Con Wanna Go.', '{"es":"Grafitis, hip hop y escaleras eléctricas al aire libre en el barrio que se convirtió en símbolo de la transformación de Medellín.","en":"Graffiti, hip hop and open-air escalators in the neighborhood that became a symbol of Medellín''s transformation."}'::jsonb, '{"es":"Una historia contada desde adentro","en":"A story told from the inside"}'::jsonb, '[{"es":"La Comuna 13 pasó de ser uno de los lugares más difíciles de Medellín a uno de sus barrios más visitados. Sus muros pintados, la música en la calle y las escaleras eléctricas que suben la ladera cuentan ese cambio mejor que cualquier libro.","en":"Comuna 13 went from being one of the toughest places in Medellín to one of its most visited neighborhoods. Its painted walls, street music and the escalators climbing the hillside tell that change better than any book."},{"es":"Lo recorres con guías que nacieron y crecieron en el barrio. Ellos te muestran sus calles, te presentan a artistas locales y te explican el significado de cada mural.","en":"You walk it with guides who were born and raised in the neighborhood. They show you their streets, introduce you to local artists and explain the meaning behind each mural."}]'::jsonb, '[{"titulo":{"es":"Grafitour","en":"Graffiti tour"},"texto":{"es":"Los murales más importantes, explicados por quienes los vieron nacer.","en":"The key murals, explained by the people who watched them being painted."}},{"titulo":{"es":"Escaleras eléctricas","en":"Outdoor escalators"},"texto":{"es":"El recorrido por las escaleras que cambiaron la vida de la ladera.","en":"A ride up the escalators that changed life on the hillside."}},{"titulo":{"es":"Hip hop y baile","en":"Hip hop and dance"},"texto":{"es":"Música y baile en la calle con los grupos del barrio.","en":"Street music and dance with local crews."}},{"titulo":{"es":"Sabores del barrio","en":"Neighborhood flavors"},"texto":{"es":"Paletas artesanales, empanadas y café en negocios locales.","en":"Handmade ice pops, empanadas and coffee at local businesses."}}]'::jsonb, '{"llegar":{"es":"En Medellín, desde la estación San Javier del metro","en":"In Medellín, from the San Javier metro station"},"epoca":{"es":"Todo el año","en":"Year-round"},"tiempo":{"es":"Medio día","en":"Half a day"},"ideal":{"es":"Viajeros curiosos y grupos","en":"Curious travelers and groups"}}'::jsonb, array['plazas-de-mercado', 'guatape', 'cartagena']::text[]);
insert into public.destinos (url, orden, nombre, h1, region, corto, foto, alt, foto2, alt2, titulo_seo, descripcion_seo, lead, h2, parrafos, vivir, datos, otros) values ('cartagena', 3, '{"es":"Cartagena","en":"Cartagena"}'::jsonb, '{"es":"Cartagena de Indias","en":"Cartagena de Indias"}'::jsonb, '{"es":"Caribe colombiano · Bolívar","en":"Colombian Caribbean · Bolívar"}'::jsonb, '{"es":"La ciudad amurallada y el mar Caribe.","en":"The walled city and the Caribbean Sea."}'::jsonb, 'cartagena-casas.jpg', '{"es":"Casas coloniales de colores en el centro histórico de Cartagena","en":"Colorful colonial houses in the historic center of Cartagena"}'::jsonb, 'cartagena.jpg', '{"es":"Calle colonial de Cartagena con faroles","en":"Colonial street in Cartagena with lanterns"}'::jsonb, '{"es":"Viaje a Cartagena de Indias a tu medida · Wanna Go","en":"Tailor-made trip to Cartagena de Indias · Wanna Go"}'::jsonb, 'Viaje a Cartagena a tu medida: ciudad amurallada, Getsemaní e Islas del Rosario, con hoteles boutique y guías locales. Diseñado desde Medellín por Wanna Go.', '{"es":"Murallas, balcones con flores y atardeceres sobre el Caribe. La ciudad amurallada vista con calma, lejos del recorrido de siempre.","en":"City walls, flower-draped balconies and sunsets over the Caribbean. The walled city seen calmly, away from the usual route."}'::jsonb, '{"es":"La ciudad que se camina despacio","en":"A city meant to be walked slowly"}'::jsonb, '[{"es":"El centro histórico de Cartagena, con su puerto, sus fortalezas y su conjunto monumental, es Patrimonio de la Humanidad de la UNESCO desde 1984. Sus calles coloniales, plazas y casas de colores se disfrutan mejor a pie, al ritmo del Caribe.","en":"Cartagena''s historic center, with its port, fortresses and monumental ensemble, has been a UNESCO World Heritage Site since 1984. Its colonial streets, squares and colorful houses are best enjoyed on foot, at a Caribbean pace."},{"es":"Diseñamos tu viaje combinando la ciudad amurallada, el barrio de Getsemaní y el mar de las Islas del Rosario, con hoteles boutique y restaurantes que hemos probado.","en":"We design your trip combining the walled city, the Getsemaní neighborhood and the sea around the Rosario Islands, with boutique hotels and restaurants we have tried ourselves."}]'::jsonb, '[{"titulo":{"es":"Ciudad amurallada","en":"The walled city"},"texto":{"es":"Plazas, iglesias y balcones con un guía local.","en":"Squares, churches and balconies with a local guide."}},{"titulo":{"es":"Getsemaní","en":"Getsemaní"},"texto":{"es":"Murales, música y la vida de barrio al caer la tarde.","en":"Murals, music and neighborhood life as evening falls."}},{"titulo":{"es":"Islas del Rosario","en":"Rosario Islands"},"texto":{"es":"Un día de mar turquesa y playas tranquilas.","en":"A day of turquoise water and quiet beaches."}},{"titulo":{"es":"Cocina del Caribe","en":"Caribbean cuisine"},"texto":{"es":"Pescado fresco, arroz con coco y frutas tropicales.","en":"Fresh fish, coconut rice and tropical fruit."}}]'::jsonb, '{"llegar":{"es":"Vuelo directo desde Medellín","en":"Direct flight from Medellín"},"epoca":{"es":"De diciembre a abril, la temporada más seca","en":"December to April, the driest season"},"tiempo":{"es":"3 a 4 días","en":"3 to 4 days"},"ideal":{"es":"Parejas, amigas y celebraciones","en":"Couples, friends and celebrations"}}'::jsonb, array['tayrona', 'eje-cafetero', 'guatape']::text[]);
insert into public.destinos (url, orden, nombre, h1, region, corto, foto, alt, foto2, alt2, titulo_seo, descripcion_seo, lead, h2, parrafos, vivir, datos, otros) values ('valle-de-cocora', 4, '{"es":"Valle de Cocora","en":"Cocora Valley"}'::jsonb, '{"es":"Valle de Cocora y Salento","en":"Cocora Valley and Salento"}'::jsonb, '{"es":"Quindío · Eje Cafetero","en":"Quindío · Coffee Region"}'::jsonb, '{"es":"Caminatas entre las palmas de cera.","en":"Hikes among the wax palms."}'::jsonb, 'salento.jpg', '{"es":"Palmas de cera en el valle de Cocora","en":"Wax palms in the Cocora Valley"}'::jsonb, 'cafe.jpg', '{"es":"Granos de café maduros en la rama","en":"Ripe coffee cherries on the branch"}'::jsonb, '{"es":"Valle de Cocora y Salento: palmas de cera · Wanna Go","en":"Cocora Valley and Salento: wax palms · Wanna Go"}'::jsonb, 'Camina entre las palmas de cera del Valle de Cocora, conoce Salento y visita una finca cafetera. Viaje al Quindío diseñado por Wanna Go.', '{"es":"Caminar entre palmas de cera, el árbol nacional de Colombia, en un valle de niebla y montaña a las afueras de Salento.","en":"Walk among wax palms, Colombia''s national tree, in a misty mountain valley just outside Salento."}'::jsonb, '{"es":"El valle de las palmas más altas","en":"The valley of the tallest palms"}'::jsonb, '[{"es":"La palma de cera del Quindío es el árbol nacional de Colombia y una de las palmas más altas del mundo: puede llegar a los 60 metros. En el Valle de Cocora crecen cientos de ellas sobre potreros verdes y laderas cubiertas de niebla.","en":"The Quindío wax palm is Colombia''s national tree and one of the tallest palms in the world: it can reach 60 meters. Hundreds of them rise over green pastures and mist-covered slopes in the Cocora Valley."},{"es":"Combinamos la caminata con Salento, uno de los pueblos más tradicionales del Eje Cafetero, y con una finca cafetera para entender el café desde la semilla hasta la taza.","en":"We pair the hike with Salento, one of the most traditional towns in the Coffee Region, and with a coffee farm to understand coffee from seed to cup."}]'::jsonb, '[{"titulo":{"es":"Caminata entre palmas","en":"Hike among the palms"},"texto":{"es":"Senderos de distintos niveles, a tu ritmo.","en":"Trails for different levels, at your own pace."}},{"titulo":{"es":"Salento","en":"Salento"},"texto":{"es":"Calle Real, balcones de colores y artesanías.","en":"Calle Real, colorful balconies and local crafts."}},{"titulo":{"es":"Finca cafetera","en":"Coffee farm"},"texto":{"es":"Recolección, tostión y cata con productores.","en":"Picking, roasting and tasting with growers."}},{"titulo":{"es":"Trucha y patacón","en":"Trout and patacón"},"texto":{"es":"El plato típico del valle, frente a las montañas.","en":"The valley''s classic dish, with mountain views."}}]'::jsonb, '{"llegar":{"es":"Vuelo a Pereira o Armenia y 1 hora por carretera","en":"Flight to Pereira or Armenia, then 1 hour by road"},"epoca":{"es":"Todo el año; las mañanas suelen ser más despejadas","en":"Year-round; mornings tend to be clearer"},"tiempo":{"es":"2 o 3 días con Salento","en":"2 or 3 days including Salento"},"ideal":{"es":"Amantes de la naturaleza y la caminata","en":"Nature and hiking lovers"}}'::jsonb, array['eje-cafetero', 'guatape', 'tayrona']::text[]);
insert into public.destinos (url, orden, nombre, h1, region, corto, foto, alt, foto2, alt2, titulo_seo, descripcion_seo, lead, h2, parrafos, vivir, datos, otros) values ('tayrona', 5, '{"es":"Parque Tayrona","en":"Tayrona Park"}'::jsonb, '{"es":"Parque Nacional Natural Tayrona","en":"Tayrona National Natural Park"}'::jsonb, '{"es":"Caribe colombiano · Magdalena","en":"Colombian Caribbean · Magdalena"}'::jsonb, '{"es":"Selva y playas al pie de la Sierra Nevada.","en":"Jungle and beaches at the foot of the Sierra Nevada."}'::jsonb, 'tayrona.jpg', '{"es":"Playa del Parque Tayrona con selva y rocas junto al mar","en":"Tayrona Park beach with jungle and boulders by the sea"}'::jsonb, 'grupo-atardecer.jpg', '{"es":"Grupo de viajeros contemplando el atardecer","en":"Group of travelers watching the sunset"}'::jsonb, '{"es":"Viaje al Parque Tayrona con Wanna Go","en":"Trip to Tayrona Park with Wanna Go"}'::jsonb, 'Viaje al Parque Tayrona: senderos de selva, Cabo San Juan y la cultura de la Sierra Nevada de Santa Marta, con guías locales. Diseñado por Wanna Go.', '{"es":"Selva que baja de la Sierra Nevada hasta playas de arena dorada. Un parque nacional para recorrer con respeto y sin prisa.","en":"Jungle that runs down from the Sierra Nevada to golden-sand beaches. A national park to explore respectfully and unhurried."}'::jsonb, '{"es":"Donde la sierra se encuentra con el mar","en":"Where the mountains meet the sea"}'::jsonb, '[{"es":"El Parque Nacional Natural Tayrona, cerca de Santa Marta, protege bosques, bahías y playas al pie de la Sierra Nevada de Santa Marta, territorio ancestral de los pueblos kogui, arhuaco, wiwa y kankuamo.","en":"Tayrona National Natural Park, near Santa Marta, protects forests, bays and beaches at the foot of the Sierra Nevada de Santa Marta, ancestral land of the Kogi, Arhuaco, Wiwa and Kankuamo peoples."},{"es":"Organizamos tu visita con guías locales, alojamiento en la zona y los tiempos del parque, que cierra algunas temporadas al año para su descanso ecológico. Te confirmamos las fechas antes de reservar.","en":"We plan your visit with local guides, nearby lodging and the park schedule, since it closes for a few periods each year to let the ecosystem rest. We confirm the dates before booking."}]'::jsonb, '[{"titulo":{"es":"Senderos de selva","en":"Jungle trails"},"texto":{"es":"Caminatas entre bosque tropical, monos y rocas gigantes.","en":"Walks through tropical forest, monkeys and giant boulders."}},{"titulo":{"es":"Cabo San Juan","en":"Cabo San Juan"},"texto":{"es":"Una de las playas más bonitas del Caribe colombiano.","en":"One of the most beautiful beaches on Colombia''s Caribbean coast."}},{"titulo":{"es":"Cultura de la Sierra","en":"Culture of the Sierra"},"texto":{"es":"Un acercamiento a la visión de los pueblos indígenas de la Sierra Nevada.","en":"An introduction to the worldview of the Sierra Nevada''s Indigenous peoples."}},{"titulo":{"es":"Santa Marta","en":"Santa Marta"},"texto":{"es":"La ciudad más antigua de Colombia, como base del viaje.","en":"Colombia''s oldest city, as your base."}}]'::jsonb, '{"llegar":{"es":"Vuelo directo a Santa Marta y 1 hora por carretera","en":"Direct flight to Santa Marta, then 1 hour by road"},"epoca":{"es":"De diciembre a abril, la temporada más seca","en":"December to April, the driest season"},"tiempo":{"es":"3 a 4 días","en":"3 to 4 days"},"ideal":{"es":"Naturaleza, mar y aventura suave","en":"Nature, sea and gentle adventure"}}'::jsonb, array['cartagena', 'valle-de-cocora', 'comuna-13']::text[]);
insert into public.destinos (url, orden, nombre, h1, region, corto, foto, alt, foto2, alt2, titulo_seo, descripcion_seo, lead, h2, parrafos, vivir, datos, otros) values ('eje-cafetero', 6, '{"es":"Eje Cafetero","en":"Coffee Region"}'::jsonb, '{"es":"Eje Cafetero","en":"Coffee Region"}'::jsonb, '{"es":"Caldas, Risaralda y Quindío","en":"Caldas, Risaralda and Quindío"}'::jsonb, '{"es":"Fincas, pueblos y café de origen.","en":"Farms, villages and single-origin coffee."}'::jsonb, 'cafe.jpg', '{"es":"Granos de café maduros en la rama","en":"Ripe coffee cherries on the branch"}'::jsonb, 'salento.jpg', '{"es":"Palmas de cera en el valle de Cocora","en":"Wax palms in the Cocora Valley"}'::jsonb, '{"es":"Viaje al Eje Cafetero: fincas y café · Wanna Go","en":"Trip to the Coffee Region: farms and coffee · Wanna Go"}'::jsonb, 'Viaje al Eje Cafetero de Colombia: fincas cafeteras, Salento, Filandia y el Valle de Cocora, en el Paisaje Cultural Cafetero. Diseñado por Wanna Go.', '{"es":"Montañas sembradas de café, pueblos de bahareque y fincas donde el día empieza con una taza recién hecha.","en":"Coffee-planted mountains, bahareque villages and farms where the day starts with a freshly brewed cup."}'::jsonb, '{"es":"Un paisaje que es patrimonio","en":"A landscape that is World Heritage"}'::jsonb, '[{"es":"El Paisaje Cultural Cafetero de Colombia es Patrimonio Mundial de la UNESCO desde 2011. Reconoce una forma de vida: familias que cultivan café en laderas empinadas desde hace generaciones y pueblos con arquitectura de colores.","en":"Colombia''s Coffee Cultural Landscape has been a UNESCO World Heritage Site since 2011. It recognizes a way of life: families who have grown coffee on steep slopes for generations and villages with colorful architecture."},{"es":"Te llevamos a fincas donde los productores te enseñan su oficio, a pueblos como Filandia y Salento, y a paisajes como el Valle de Cocora. Dormir en una finca es parte del viaje.","en":"We take you to farms where growers share their craft, to villages like Filandia and Salento, and to landscapes like the Cocora Valley. Staying on a farm is part of the trip."}]'::jsonb, '[{"titulo":{"es":"Del grano a la taza","en":"From bean to cup"},"texto":{"es":"Recolección, secado, tostión y cata con una familia cafetera.","en":"Picking, drying, roasting and tasting with a coffee-growing family."}},{"titulo":{"es":"Filandia y Salento","en":"Filandia and Salento"},"texto":{"es":"Pueblos de balcones de colores y miradores.","en":"Villages of colorful balconies and lookouts."}},{"titulo":{"es":"Dormir en una finca","en":"Stay on a farm"},"texto":{"es":"Casas tradicionales rodeadas de cafetales.","en":"Traditional houses surrounded by coffee plantations."}},{"titulo":{"es":"Termales y naturaleza","en":"Hot springs and nature"},"texto":{"es":"Aguas termales, avistamiento de aves y jardines botánicos.","en":"Hot springs, birdwatching and botanical gardens."}}]'::jsonb, '{"llegar":{"es":"Vuelo a Pereira o Armenia, o 5 a 6 horas por carretera desde Medellín","en":"Flight to Pereira or Armenia, or 5 to 6 hours by road from Medellín"},"epoca":{"es":"Todo el año; la cosecha principal va de septiembre a diciembre","en":"Year-round; the main harvest runs from September to December"},"tiempo":{"es":"3 a 5 días","en":"3 to 5 days"},"ideal":{"es":"Amantes del café, familias y parejas","en":"Coffee lovers, families and couples"}}'::jsonb, array['valle-de-cocora', 'guatape', 'plazas-de-mercado']::text[]);
insert into public.destinos (url, orden, nombre, h1, region, corto, foto, alt, foto2, alt2, titulo_seo, descripcion_seo, lead, h2, parrafos, vivir, datos, otros) values ('plazas-de-mercado', 7, '{"es":"Plazas de mercado","en":"Local markets"}'::jsonb, '{"es":"Plazas de mercado de Medellín","en":"Medellín''s market halls"}'::jsonb, '{"es":"Medellín","en":"Medellín"}'::jsonb, '{"es":"Frutas exóticas y cocina popular.","en":"Exotic fruit and home-style cooking."}'::jsonb, 'frutas.jpg', '{"es":"Puesto de frutas tropicales en una plaza de mercado","en":"Tropical fruit stall at a market hall"}'::jsonb, 'medellin.jpg', '{"es":"Medellín iluminada al atardecer, rodeada de montañas","en":"Medellín lit up at dusk, surrounded by mountains"}'::jsonb, '{"es":"Tour de frutas en plazas de mercado de Medellín · Wanna Go","en":"Fruit tour in Medellín market halls · Wanna Go"}'::jsonb, 'Tour de frutas exóticas por las plazas de mercado de Medellín: cata en el puesto, yerbateros y almuerzo típico, con guías locales de Wanna Go.', '{"es":"Lulo, granadilla, maracuyá, guanábana. Colombia se prueba en sus plazas de mercado, entre puestos de frutas, hierbas y cocina popular.","en":"Lulo, granadilla, passion fruit, soursop. Colombia is tasted in its market halls, among stalls of fruit, herbs and home-style cooking."}'::jsonb, '{"es":"La despensa de Medellín","en":"Medellín''s pantry"}'::jsonb, '[{"es":"Las plazas de mercado son el lugar donde se cruza todo Antioquia: campesinos, cocineras, yerbateros y vendedores que llevan toda la vida en el mismo puesto. Colombia tiene una enorme variedad de frutas y aquí se ve, se huele y se prueba.","en":"Market halls are where all of Antioquia meets: farmers, cooks, herbalists and vendors who have spent a lifetime at the same stall. Colombia has an enormous variety of fruit, and here you see it, smell it and taste it."},{"es":"Recorremos plazas como la Minorista con guías locales, probamos frutas que no encontrarás en otro país y terminamos en la mesa, con un almuerzo típico.","en":"We walk through market halls like La Minorista with local guides, taste fruit you won''t find anywhere else and finish at the table with a traditional lunch."}]'::jsonb, '[{"titulo":{"es":"Cata de frutas","en":"Fruit tasting"},"texto":{"es":"Frutas exóticas explicadas y probadas en el puesto.","en":"Exotic fruits explained and tasted right at the stall."}},{"titulo":{"es":"Hierbas y saberes","en":"Herbs and folk wisdom"},"texto":{"es":"Los yerbateros y sus remedios tradicionales.","en":"Herbalists and their traditional remedies."}},{"titulo":{"es":"Almuerzo de plaza","en":"Market lunch"},"texto":{"es":"Sopa, frijoles o sancocho donde comen los que trabajan ahí.","en":"Soup, beans or sancocho where the market workers eat."}},{"titulo":{"es":"Café y arepa","en":"Coffee and arepa"},"texto":{"es":"Desayuno paisa para empezar con energía.","en":"A paisa breakfast to start the day."}}]'::jsonb, '{"llegar":{"es":"En Medellín, cerca del centro","en":"In Medellín, near downtown"},"epoca":{"es":"Todo el año, mejor en la mañana","en":"Year-round, best in the morning"},"tiempo":{"es":"Medio día","en":"Half a day"},"ideal":{"es":"Viajeros curiosos y amantes de la cocina","en":"Curious travelers and food lovers"}}'::jsonb, array['comuna-13', 'guatape', 'eje-cafetero']::text[]);
